const item = $input.item.json;
const company = (item.Company_Name || '').toString().trim();
const city = (item.City || '').toString().trim();

if (!company || !city) {
  return {
    json: {
      ...item,
      isValid: false,
      errorMessage: !company ? 'Company_Name is required' : 'City is required',
      Research_Status: 'Failed',
      Error_Details: !company ? 'Missing required field: Company_Name' : 'Missing required field: City',
      Lead_Confidence: 'Low',
      Outreach_Status: 'Not Ready',
      Followup_Status: 'Not Scheduled',
      Updated_At: new Date().toISOString()
    }
  };
}

return {
  json: {
    ...item,
    Company_Name: company,
    City: city,
    isValid: true
  }
};

const currentLead = $('Validate Input').item.json;
const allRows = $input.all().map(i => i.json);

function norm(s) {
  return (s || '').toString().toLowerCase().replace(/[^\w\s]/g, ' ').replace(/\s+/g, ' ').trim();
}

const targetComp = norm(currentLead.Company_Name);
const targetCity = norm(currentLead.City);
const currentRowNum = currentLead.row_number;

const match = allRows.find(r => {
  if (currentRowNum && r.row_number === currentRowNum) return false;
  const compMatch = norm(r.Company_Name) === targetComp;
  const cityMatch = norm(r.City) === targetCity;
  if (!compMatch || !cityMatch) return false;

  const status = (r.Research_Status || '').toLowerCase().trim();
  const outreach = (r.Outreach_Status || '').toLowerCase().trim();
  return ['completed', 'processing', 'needs review', 'duplicate'].includes(status) ||
         ['draft created', 'sent (test)', 'sent'].includes(outreach);
});

if (match) {
  return {
    json: {
      ...currentLead,
      isDuplicate: true,
      duplicateReason: `Duplicate: '${currentLead.Company_Name}' in '${currentLead.City}' already exists in database.`
    }
  };
}

return {
  json: {
    ...currentLead,
    isDuplicate: false,
    Research_Status: 'Processing'
  }
};

