const prev = $('Parse & Rank Lead').item.json;
const aiRaw = $input.item.json;
let parsed = null;

try {
  const text = aiRaw.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  parsed = JSON.parse(text);
} catch (e) {
  return {
    json: {
      ...prev,
      AI_Pitch: 'Parsing failed: Invalid JSON returned by AI',
      Email_Subject: `Event Coordination Support for ${prev.Company_Name}`,
      Research_Status: 'Needs Review',
      Error_Details: 'AI JSON parsing error. Requires human review.',
      Updated_At: new Date().toISOString()
    }
  };
}

const l1 = (parsed.pitch_line_1 || '').trim();
const l2 = (parsed.pitch_line_2 || '').trim();
const l3 = (parsed.pitch_line_3 || '').trim();

if (!l1 || !l2 || !l3) {
  return {
    json: {
      ...prev,
      AI_Pitch: 'Validation failed: Pitch did not contain exactly three lines',
      Email_Subject: parsed.email_subject || `Event Vendor Network for ${prev.Company_Name}`,
      Research_Status: 'Needs Review',
      Error_Details: 'Pitch validation failed (fewer than 3 lines).',
      Updated_At: new Date().toISOString()
    }
  };
}

const pitchText = `${l1}\n${l2}\n${l3}`;

return {
  json: {
    ...prev,
    AI_Pitch: pitchText,
    Email_Subject: parsed.email_subject || `Event Coordination for ${prev.Company_Name}`,
    Research_Status: prev.Lead_Confidence === 'Low' || prev.Lead_Name === 'Not Found' ? 'Needs Review' : 'Completed',
    Updated_At: new Date().toISOString()
  }
};
